import React, { useContext, useEffect, useRef } from 'react';
import context from '../context/Notecontext';
import Noteitem from './Noteitem';
import Addnote from './Addnote';

const Notes = () => {
    const ref = useRef(null);

    const Context = useContext(context);
    const { notes, getnotes } = Context;
    useEffect(() => {
        getnotes();
        // eslint-disable-next-line
    }, [])

    const updatenote = (note) => {
        ref.current.click();
    }
    return (
        <>
            <Addnote />
            <button ref={ref} type="button" className="btn btn-primary " data-bs-toggle="modal" data-bs-target="#exampleModal">
                Launch demo modal
            </button>
            <div className="modal fade" id="exampleModal" tabIndex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
                <div className="modal-dialog">
                    <div className="modal-content">
                        <div className="modal-header">
                            <h5 className="modal-title" id="exampleModalLabel">Edit Note</h5>
                            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                        </div>
                        <div className="modal-body">
                            <div className='container mt-2'>
                                <h2>Add a Note</h2>
                                <div className="mb-3 my-1">
                                    <label htmlFor="title" className="form-label">Title</label>
                                    <input type="text" className="form-control" id="title" name='title' style={{ "width": "300px" }} onChange={onChange} />
                                </div>
                                <div className="col-auto my-2">
                                    <label htmlFor="description">Description</label>
                                    <input type="text" className="form-control" id="description" name='description' style={{ "width": "300px" }} onChange={onChange} />
                                </div>
                                <div className="col-auto my-2">
                                    <label htmlFor="tag">Tag</label>
                                    <input type="text" className="form-control" id="tag" name='tag' style={{ "width": "300px" }} onChange={onChange} />
                                </div>
                                <div className="col-auto mt-3">
                                    <button type="submit" className="btn btn-info mb-3" onClick={handleclick}>Submit</button>
                                </div>
                            </div>
                        </div>
                        <div className="modal-footer">
                            <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">Close</button>
                            <button type="button" className="btn btn-primary">Update Note</button>
                        </div>
                    </div>
                </div>
            </div>
            <div className='container'>
                <h2>Your Notes</h2>
            </div>
            <div className='row'>
                {notes.map((note) => {
                    return <Noteitem key={note._id} updatenote={updatenote} note={note} />
                })}
            </div>
        </>
    )
}

export default Notes
